//! Static text for every language the desktop app offers (US-I18N-01).
//!
//! Each message is one row of seven strings, in the order of [`Language::ALL`]:
//! English, Hindi, Sanskrit, Tamil, Telugu, Malayalam, Urdu. The array type makes a missing translation a compile error.
//! `{0}`, `{1}` mark where [`trf`] puts a value, so a translation can move it to wherever its grammar wants it.
//! Text that comes from libraries (the password-strength warnings and the cracking time) stays in English.
use rahasyakosh_app::Language;

macro_rules! messages {
    ($($key:ident => [$en:expr, $hi:expr, $sa:expr, $ta:expr, $te:expr, $ml:expr, $ur:expr]),+ $(,)?) => {
        /// Every piece of text the app shows.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        pub enum Msg { $($key),+ }

        impl Msg {
            pub const ALL: &'static [Msg] = &[$(Msg::$key),+];

            fn row(self) -> [&'static str; 7] {
                match self { $(Msg::$key => [$en, $hi, $sa, $ta, $te, $ml, $ur]),+ }
            }
        }
    };
}

/// The text of `msg` in `lang`.
pub fn t(lang: Language, msg: Msg) -> &'static str {
    msg.row()[lang.index()]
}

/// The text of `msg` in `lang` with `{0}`, `{1}`... replaced by `args`.
pub fn trf(lang: Language, msg: Msg, args: &[&dyn std::fmt::Display]) -> String {
    let mut s = t(lang, msg).to_string();
    for (i, a) in args.iter().enumerate() {
        s = s.replace(&format!("{{{i}}}"), &a.to_string());
    }
    s
}

